import json, pickle
def solve(data):
    original = tuple(data)
    from_json = json.loads(json.dumps(original))
    from_pickle = pickle.loads(pickle.dumps(original))
    return {'json_type':type(from_json).__name__, 'pickle_type':type(from_pickle).__name__, 'json_values':from_json, 'pickle_values':list(from_pickle)}
